if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_device_cache() {
    cat <<-'EOF'
	?	report device cache file paths
	b	build the device cache file
	i	ignore the device cache file
	r	read the device cache file
	u	read and update the device cache file
	EOF
}

_choice_fd() {
    cat <<-'EOF' | _argc_util_comp_multi ,
	cwd	current working directory
	err	FD information error
	jld	jail directory
	ltx	shared library text
	mem	memory-mapped file
	mmap	memory-mapped device
	pd	parent directory
	rtd	root directory
	twd	per task current working directory
	txt	program text
	EOF
}

_choice_pgid() {
    ps -Ao pgid=,args= 2>/dev/null | gawk '
        {
            pgid = $1
            desc = $0
            sub(/^[[:space:]]*/, "", desc)
            sub(/^[^[:space:]]+[[:space:]]+/, "", desc)
            if (length(desc) > 70) {
                desc = substr(desc, 1, 67) "..."
            }
            if (pgid in seen) {
                next
            }
            seen[pgid] = 1
            if (desc == "") {
                print pgid
            } else {
                printf "%s\t%s\n", pgid, desc
            }
        }'
}

_choice_pid() {
    ps -Ao pid=,args= 2>/dev/null | gawk '
        {
            pid = $1
            desc = $0
            sub(/^[[:space:]]*/, "", desc)
            sub(/^[^[:space:]]+[[:space:]]+/, "", desc)
            if (length(desc) > 70) {
                desc = substr(desc, 1, 67) "..."
            }
            if (desc == "") {
                print pid
            } else {
                printf "%s\t%s\n", pid, desc
            }
        }'
}

_choice_process() {
    ps -Ao comm= 2>/dev/null | gawk '
        {
            sub(/^[[:space:]]+/, "")
            sub(/.*\//, "")
            if ($0 != "") {
                print
            }
        }'
}

_choice_protocol_state() {
    cat <<-'EOF' | _argc_util_comp_kv :
	TCP=CLOSED,IDLE,BOUND,LISTEN,SYN_SENT,SYN_RCVD,ESTABLISHED,CLOSE_WAIT,FIN_WAIT1,FIN_WAIT_2,CLOSING,LAST_ACK,TIME_WAIT;;TCP protocol states
	UDP=Unbound,Idle;;UDP protocol states
	EOF
}

_choice_user() {
    compgen -u
}
